namespace Arena.Matchmaking.Tests;

public class RankedPingTests
{
    private readonly LobbyAssigner _assigner = new();

    [Fact]
    public void HighPingPlayerSkipsRankedLobby()
    {
        var player = Players.Make(region: "eu", mmr: 1500, pingMs: 180);
        Assert.Null(_assigner.Assign(player, [Lobbies.Ranked("ranked-eu-1", "eu", 1500)]));
    }

    [Fact]
    public void HighPingPlayerFallsBackToCasualLobby()
    {
        var player = Players.Make(region: "eu", mmr: 1500, pingMs: 180);
        Lobby[] open = [Lobbies.Ranked("ranked-eu-1", "eu", 1500), Lobbies.Casual("casual-eu-2", "eu")];
        Assert.Equal("casual-eu-2", _assigner.Assign(player, open)?.Id);
    }

    [Fact]
    public void PingAtLimitIsAllowedInRanked()
    {
        var player = Players.Make(region: "eu", mmr: 1500, pingMs: 150);
        Assert.Equal("ranked-eu-1", _assigner.Assign(player, [Lobbies.Ranked("ranked-eu-1", "eu", 1500)])?.Id);
    }
}

