package com.acme.shop.orders;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.http.MediaType;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;

@WebMvcTest(OrderController.class)
class OrderInvoiceEndpointTest {
    @Autowired MockMvc mvc;
    @MockitoBean OrderRepository orders;
    @MockitoBean InvoiceRenderer renderer;

    @Test @WithMockUser
    void returnsPdfForExistingOrder() throws Exception {
        when(orders.findById(7L)).thenReturn(Optional.of(Orders.sample(7L)));
        when(renderer.render(any())).thenReturn(new byte[] {37, 80, 68, 70});
        mvc.perform(get("/api/orders/7/invoice"))
           .andExpect(status().isOk())
           .andExpect(content().contentType(MediaType.APPLICATION_PDF));
    }

    @Test @WithMockUser
    void returns404ForUnknownOrder() throws Exception {
        mvc.perform(get("/api/orders/999/invoice").accept(MediaType.APPLICATION_JSON))
           .andExpect(status().isNotFound());
    }

    @Test
    void requiresAuthentication() throws Exception {
        mvc.perform(get("/api/orders/7/invoice")).andExpect(status().isUnauthorized());
    }
}
